#!/usr/bin/env node
/**
 * Bootstrap android/local.properties on cold checkouts.
 *
 * Gradle requires android/local.properties to point at the Android SDK before
 * `npm run android` will work. The file is gitignored upstream — env-specific
 * paths shouldn't be committed — so every fresh worktree needs it written
 * before first build.
 *
 * Behavior:
 *   - If android/local.properties already exists: no-op.
 *   - If $ANDROID_HOME is set: write `sdk.dir=$ANDROID_HOME`.
 *   - Else, on macOS: write `sdk.dir=$HOME/Library/Android/sdk` if it exists.
 *   - Else, on linux: write `sdk.dir=$HOME/Android/Sdk` if it exists.
 *   - Else: print a friendly diagnostic and exit 0 (don't break npm install).
 *
 * Sprint 17 (S17.10 / TECH_DEBT #46): also handles a missing .env.local in
 * worktrees — `npm install`'s `postinstall` runs reliably, but contributors
 * sometimes copy a worktree by other means or skip `npm install` after
 * `git worktree add`. Running `npm run bootstrap` directly is the explicit
 * recovery path. If `.env.local` is missing AND a sibling worktree has one,
 * we surface the path so the contributor can copy it manually (we do NOT
 * copy automatically — secrets in `.env.local` could be stale).
 *
 * 2026-08-30 (TECH_DEBT #206): also checks for a Java 17 TOOLCHAIN. React
 * Native and expo-modules-core declare `jvmToolchain(17)`, which is a separate
 * requirement from the JDK that launches Gradle (21). With no 17 installed,
 * Gradle tries to auto-provision one through the foojay resolver pinned at
 * 0.5.0 by @react-native/gradle-plugin, which is incompatible with this repo's
 * Gradle 9 and dies with:
 *
 *   Class org.gradle.jvm.toolchain.JvmVendorSpec does not have member field
 *   'org.gradle.jvm.toolchain.JvmVendorSpec IBM_SEMERU'
 *
 * That message names neither Java nor the missing toolchain, so it costs real
 * time to diagnose. Having 21 and 25 installed is NOT enough. Warn early.
 *
 * Run by package.json `postinstall` after patch-package, and exposed as
 * `npm run bootstrap` for explicit re-run.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');

function main() {
  const androidDir = path.join(__dirname, '..', 'android');
  // Worktree may not have android/ if `expo prebuild --clean` hasn't been run.
  if (!fs.existsSync(androidDir)) return;

  const target = path.join(androidDir, 'local.properties');
  if (fs.existsSync(target)) return; // already set, never overwrite

  const envSdk = process.env.ANDROID_HOME || process.env.ANDROID_SDK_ROOT;
  let sdkDir = envSdk;

  if (!sdkDir && process.platform === 'darwin') {
    const candidate = path.join(os.homedir(), 'Library', 'Android', 'sdk');
    if (fs.existsSync(candidate)) sdkDir = candidate;
  }
  if (!sdkDir && process.platform === 'linux') {
    const candidate = path.join(os.homedir(), 'Android', 'Sdk');
    if (fs.existsSync(candidate)) sdkDir = candidate;
  }

  if (!sdkDir) {
    // Don't fail — the developer may not be doing Android work right now.
    console.log(
      '[bootstrap-android] android/local.properties not written: $ANDROID_HOME unset and no ~/Library/Android/sdk found.',
    );
    console.log(
      '[bootstrap-android] To fix: export ANDROID_HOME=/path/to/sdk and re-run `npm install`, or write the file manually.',
    );
    return;
  }

  const contents = `# Auto-generated by scripts/bootstrap-android-local-properties.js
# Edit freely or delete and re-run \`npm install\` to regenerate.
sdk.dir=${sdkDir}
`;
  fs.writeFileSync(target, contents, 'utf8');
  console.log(`[bootstrap-android] Wrote ${target}`);
}

// Sprint 17 (S17.10): surface a missing .env.local on worktrees without
// silently copying — a sibling worktree's value might be stale or env-specific.
function checkEnvLocal() {
  const root = path.join(__dirname, '..');
  const target = path.join(root, '.env.local');
  if (fs.existsSync(target)) return;

  // Look one level up for sibling worktrees with .env.local already present.
  const parent = path.dirname(root);
  let sibling = null;
  try {
    for (const entry of fs.readdirSync(parent)) {
      const candidate = path.join(parent, entry, '.env.local');
      if (entry !== path.basename(root) && fs.existsSync(candidate)) {
        sibling = candidate;
        break;
      }
    }
  } catch {
    // parent directory not readable; ignore
  }

  console.log(
    '[bootstrap-android] .env.local is missing. Some features (Sentry, PostHog, QF OAuth, CDN killswitch) will be disabled.',
  );
  if (sibling) {
    console.log(
      `[bootstrap-android] A sibling worktree has one at: ${sibling}`,
    );
    console.log(
      `[bootstrap-android] If still current: cp "${sibling}" "${target}"`,
    );
  } else {
    console.log(
      '[bootstrap-android] See .env.example for the expected variable shape.',
    );
  }
}

/**
 * Where Gradle looks for JDKs on its own, plus anything the user registered
 * explicitly. A JDK in a non-standard directory (~/jdks, say) is invisible to
 * Gradle unless `org.gradle.java.installations.paths` names it, so a machine
 * can have Java 17 on disk and still fail.
 */
function javaInstallationDirs() {
  const dirs = [];
  const home = os.homedir();

  const roots =
    process.platform === 'darwin'
      ? [
          '/Library/Java/JavaVirtualMachines',
          path.join(home, 'Library', 'Java', 'JavaVirtualMachines'),
        ]
      : ['/usr/lib/jvm'];

  for (const root of roots) {
    try {
      for (const entry of fs.readdirSync(root)) {
        dirs.push(path.join(root, entry));
      }
    } catch {
      // root absent on this machine; fine
    }
  }

  // Explicitly registered installations win regardless of location.
  try {
    const gradleProps = fs.readFileSync(
      path.join(home, '.gradle', 'gradle.properties'),
      'utf8',
    );
    const line = gradleProps
      .split('\n')
      .find(l => l.trim().startsWith('org.gradle.java.installations.paths'));
    if (line) {
      const value = line.slice(line.indexOf('=') + 1);
      for (const p of value.split(',')) {
        if (p.trim()) dirs.push(p.trim());
      }
    }
  } catch {
    // no user-level gradle.properties; fine
  }

  return dirs;
}

/** Read a JDK's feature version from its release file, without running it. */
function majorVersionOf(dir) {
  for (const rel of ['release', path.join('Contents', 'Home', 'release')]) {
    try {
      const text = fs.readFileSync(path.join(dir, rel), 'utf8');
      const m = text.match(/JAVA_VERSION="?(\d+)/);
      if (m) return Number(m[1]);
    } catch {
      // not a JDK dir, or unreadable
    }
  }
  return null;
}

function checkJavaToolchain() {
  const REQUIRED = 17;
  const dirs = javaInstallationDirs();
  const found = dirs.some(d => majorVersionOf(d) === REQUIRED);
  if (found) return; // silent: the common case must not add noise

  const versions = [...new Set(dirs.map(majorVersionOf).filter(Boolean))].sort(
    (a, b) => a - b,
  );
  console.log(
    `[bootstrap-android] No JDK ${REQUIRED} found${
      versions.length ? ` (saw ${versions.join(', ')})` : ''
    }. Android builds will FAIL.`,
  );
  console.log(
    `[bootstrap-android] React Native and expo-modules-core declare jvmToolchain(${REQUIRED}); this is separate from the JDK 21 that launches Gradle, and 21 does NOT satisfy it.`,
  );
  console.log(
    '[bootstrap-android] Without it Gradle tries to auto-provision and fails with "JvmVendorSpec does not have member field \'IBM_SEMERU\'", which names neither Java nor the toolchain.',
  );
  console.log(
    `[bootstrap-android] Fix: brew install --cask temurin@${REQUIRED}  (or unpack Temurin ${REQUIRED} anywhere and add its path to org.gradle.java.installations.paths in ~/.gradle/gradle.properties)`,
  );
}

main();
checkEnvLocal();
checkJavaToolchain();
